<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login();
if(!can('media.upload')&&!can('media.approve')&&!can('media.edit_all')){http_response_code(403);exit('Media permission required.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();try{
  if(($_POST['action']??'')==='upload'){require_permission('media.upload');$file=$_FILES['asset']??[];$asset=MediaService::storeImage($file,$_POST,(int)$me['id']);if(!$asset)throw new RuntimeException('Choose an image.');audit_log('media_upload','media_asset',(int)$asset['id'],'quarantined');flash('Media was safely re-encoded into private quarantine and awaits independent rights approval.');}
  elseif(($_POST['action']??'')==='approve'){require_permission('media.approve');$id=(int)($_POST['id']??0);MediaService::approveImage($id,(int)$me['id']);audit_log('media_approve','media_asset',$id);flash('Media approved and its safe derivative is now public.');}
  elseif(($_POST['action']??'')==='reject'){require_permission('media.approve');$id=(int)($_POST['id']??0);MediaService::reject($id,(int)$me['id'],(string)($_POST['reason']??''));audit_log('media_reject','media_asset',$id);flash('Media rejected and remains private.');}
  else throw new RuntimeException('Unknown media action.');header('Location: '.path('admin/media-library.php'));exit;
 }catch(Throwable $e){$error=$e->getMessage();}
}
$assets=query_all('SELECT m.*,u.full_name FROM media_assets m JOIN users u ON u.id=m.uploaded_by ORDER BY m.created_at DESC LIMIT 200');
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Media Library · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1200px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a></p><div class="admin-section-title"><h1>Professional Media Library<span class="brand-accent">.</span></h1></div><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice"><?=e($msg)?></div><?php endif;?>
<?php if(can('media.upload')):?><section class="setting-panel"><h2>Upload licensed image</h2><p>Originals and safe derivatives remain private until a different authorized user approves rights.</p><form method="post" enctype="multipart/form-data" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="upload"><label>IMAGE<input type="file" name="asset" accept="image/jpeg,image/png,image/webp" required></label><label>TITLE<input name="title" maxlength="240" required></label><label>ALT TEXT<input name="alt_text" maxlength="500" required></label><label>CREATOR<input name="creator" maxlength="200" required></label><label>SOURCE ORGANIZATION<input name="source_organization" maxlength="200" required></label><label>LICENSE<input name="license_type" maxlength="120" required></label><label>COPYRIGHT HOLDER<input name="copyright_holder" maxlength="240" required></label><label>RIGHTS EXPIRE<input type="datetime-local" name="rights_expires_at"></label><label>CAPTION<textarea name="caption"></textarea></label><label>USAGE RESTRICTIONS<textarea name="usage_restrictions"></textarea></label><button>UPLOAD TO PRIVATE QUARANTINE →</button></form></section><?php endif;?>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ASSET</th><th>RIGHTS</th><th>STATUS</th><th>UPLOADED BY</th><th></th></tr></thead><tbody><?php foreach($assets as $a):?><tr><td><?php if($a['public_path']):?><img src="<?=e(path($a['public_path']))?>" alt="" style="width:90px;height:60px;object-fit:cover"><?php else:?><b>PRIVATE / QUARANTINED</b><?php endif;?><br><b><?=e($a['title'])?></b><br><small><?=e($a['sha256']??'')?></small></td><td><?=e($a['creator']??'')?> · <?=e($a['license_type']??'')?><br><?=e($a['copyright_holder']??'')?><?php if($a['rights_expires_at']):?><br>Expires <?=e(display_date($a['rights_expires_at']))?><?php endif;?></td><td><?=e($a['approval_status'])?> · scan <?=e($a['malware_scan_status']??'unknown')?></td><td><?=e($a['full_name'])?></td><td><?php if(can('media.approve')&&$a['approval_status']==='pending'&&(int)$a['uploaded_by']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=$a['id']?>"><button>APPROVE</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reject"><input type="hidden" name="id" value="<?=$a['id']?>"><input name="reason" minlength="10" placeholder="Rejection reason" required><button>REJECT</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
